import assert from "node:assert/strict";
import { readFile, readdir, stat } from "node:fs/promises";
import { after, test } from "node:test";
import { createServer } from "vite";

const server = await createServer({
  configFile: false,
  server: { middlewareMode: true, ws: false },
  appType: "custom"
});
after(() => server.close());
const { CATALOG, profileOf } = await server.ssrLoadModule("/src/scripts/reveal/catalog.ts");
// Captured from the object-literal catalog before tuple compaction, not regenerated by tests.
const original = JSON.parse(
  await readFile(new URL("./fixtures/reveal-catalog.json", import.meta.url))
);

test("catalog preserves all 191 original profiles and their order", () => {
  assert.equal(CATALOG.length, 191);
  assert.deepEqual(CATALOG, original);
  assert.ok(Object.isFrozen(CATALOG));
});

test("profile lookup returns the exact catalog object and undefined for absent names", () => {
  for (const [index, expected] of original.entries()) {
    assert.deepEqual(profileOf(expected.name), expected);
    assert.equal(profileOf(expected.name), CATALOG[index]);
  }
  for (const name of ["", "not-a-real-effect", "Starlight", "__proto__", "constructor"]) {
    assert.equal(profileOf(name), undefined);
  }
});

test("seeded desktop, compact and forced-color plans match original catalog fixtures", async () => {
  const { planEntry } = await server.ssrLoadModule("/src/scripts/reveal/choreography.ts");
  const { resolveTier } = await server.ssrLoadModule("/src/scripts/reveal/tiers.ts");
  // Full plans captured before compaction, including map insertion order and timing.
  const cases = [
    [
      42,
      "overview",
      1440,
      false,
      {
        frame: { motif: "flare", origin: "last", tempo: "calm", axis: "y" },
        entryNo: 1,
        seed: 4174905367,
        stepMs: 60,
        byId: [
          ["heading", { name: "num-roll", played: "num-roll", rank: 0, slotMs: 0 }],
          [
            "hero-name",
            { name: "orbital-capture", played: "orbital-capture", rank: 1, slotMs: 70 }
          ],
          ["text", { name: "blur-in", played: "blur-in", rank: 2, slotMs: 140 }],
          ["card", { name: "orbit-in", played: "orbit-in", rank: 3, slotMs: 210 }]
        ]
      }
    ],
    [
      73,
      "projects",
      390,
      false,
      {
        frame: { motif: "drift", origin: "edge", tempo: "lively", axis: "x" },
        entryNo: 1,
        seed: 2065179556,
        stepMs: 40,
        byId: [
          ["heading", { name: "starlight", played: "starlight", rank: 0, slotMs: 0 }],
          [
            "hero-name",
            { name: "hero-name-flare-sweep", played: "hero-name-flare-sweep", rank: 1, slotMs: 50 }
          ],
          ["text", { name: "fade-up", played: "fade-up", rank: 2, slotMs: 100 }],
          ["card", { name: "ring-plane", played: "ring-plane", rank: 3, slotMs: 150 }]
        ]
      }
    ],
    [
      123456,
      "contact",
      1440,
      true,
      {
        frame: { motif: "signal", origin: "edge", tempo: "calm", axis: "x" },
        entryNo: 1,
        seed: 4294876137,
        stepMs: 60,
        byId: [
          ["heading", { name: "orbit-sweep", played: "orbit-sweep", rank: 0, slotMs: 0 }],
          [
            "hero-name",
            {
              name: "hero-name-scale-settle",
              played: "hero-name-scale-settle",
              rank: 1,
              slotMs: 70
            }
          ],
          [
            "text",
            { name: "line-scan-opacity", played: "line-scan-opacity", rank: 2, slotMs: 140 }
          ],
          ["card", { name: "depth-shift", played: "depth-shift", rank: 3, slotMs: 210 }]
        ]
      }
    ]
  ];
  for (const [loadSeed, panelKey, width, forcedColors, expected] of cases) {
    const tier = resolveTier({
      width,
      height: 900,
      touch: width === 390,
      reducedMotion: false,
      reducedTransparency: false,
      forcedColors,
      saveData: false,
      zoomScale: 1
    });
    const geometry = {
      textLength: 24,
      words: 4,
      items: 3,
      focusable: false,
      splittable: true,
      hasStroke: true,
      numeric: true,
      hasNum: true,
      isLink: false,
      parts: new Set(["num", "heart", "lens", "flare", "orbit"])
    };
    const items = ["heading", "hero-name", "text", "card"].map((type, domRank) => ({
      id: type,
      type,
      geometry,
      domRank,
      extraDelayMs: domRank * 10
    }));
    const plan = planEntry({ loadSeed, panelKey, entryNo: 1, tier, items });
    assert.deepEqual(
      { ...plan, byId: [...plan.byId] },
      {
        ...expected,
        byId: expected.byId.map(([id, item]) => [
          id,
          { ...item, fallback: undefined, forcedFrom: undefined }
        ])
      },
      panelKey
    );
  }
});

// Run npm run build first: this checks emitted bytes, not source size or a new eager chunk.
test("built layout remains below 60,000 raw bytes", async () => {
  const directory = new URL("../dist/_astro/", import.meta.url);
  const files = (await readdir(directory)).filter((name) => /^BaseLayout\..*\.js$/.test(name));
  assert.equal(files.length, 1, "expected exactly one built layout script; run npm run build");
  const { size } = await stat(new URL(files[0], directory));
  assert.ok(size < 60_000, `${files[0]}: ${size} bytes must be below 60,000`);
});
